import React from 'react';
import { render, screen, fireEvent, waitFor } from '@testing-library/react';
import LoginPage from './page';
import { useAuth } from '@/contexts/auth-context';
import { vi, expect, test } from 'vitest';
import userEvent from '@testing-library/user-event';

vi.mock('@/contexts/auth-context', () => ({
  useAuth: vi.fn(),
}));

vi.mock('next/link', () => ({
  default: ({ children, href }: any) => <a href={href}>{children}</a>,
}));

vi.mock('next/navigation', () => ({
  useRouter: () => ({ push: vi.fn() })
}));

test('renders login form inputs and submits successfully, redirecting to dashboard', async () => {
  const loginMock = vi.fn().mockResolvedValue({ success: true });
  (useAuth as any).mockReturnValue({
    login: loginMock,
  });

  render(<LoginPage />);

  const emailInput = screen.getByPlaceholderText('nome@clickmarido.com.br');
  const passwordInput = screen.getByPlaceholderText('••••••••');
  const submitButton = screen.getByRole('button', { name: /entrar no painel/i });

  await userEvent.type(emailInput, 'admin@clickmarido.com.br');
  await userEvent.type(passwordInput, 'senha123');

  await userEvent.click(submitButton);

  expect(loginMock).toHaveBeenCalledWith('admin@clickmarido.com.br', 'senha123');
});

test('shows error message on credentials failure', async () => {
  const loginMock = vi.fn().mockRejectedValue(new Error('Credenciais incorretas'));
  (useAuth as any).mockReturnValue({
    login: loginMock,
  });

  render(<LoginPage />);

  const emailInput = screen.getByPlaceholderText('nome@clickmarido.com.br');
  const passwordInput = screen.getByPlaceholderText('••••••••');
  const submitButton = screen.getByRole('button', { name: /entrar no painel/i });

  await userEvent.type(emailInput, 'errado@clickmarido.com.br');
  await userEvent.type(passwordInput, 'senha');

  await userEvent.click(submitButton);

  await waitFor(() => {
    expect(screen.getByText('Credenciais incorretas')).toBeInTheDocument();
  });
});

"use client";

import React, { useState } from "react";
import Link from "next/link";
import { useAuth } from "@/contexts/auth-context";
import { Wrench, Mail, Lock, Loader2, ArrowRight } from "lucide-react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";

export default function LoginPage() {
  const { login } = useAuth();

  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError(null);

    try {
      await login(email, password);
    } catch (err: unknown) {
      setError(err.message || "E-mail ou senha inválidos. Tente novamente.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center p-4 bg-zinc-50 dark:bg-zinc-950 transition-colors duration-300 relative overflow-hidden">
      {/* Background Decorative Blobs */}
      <div className="absolute top-[-10%] right-[-10%] w-[500px] h-[500px] rounded-full bg-amber-500/10 dark:bg-amber-500/5 blur-[120px] -z-10" />
      <div className="absolute bottom-[-10%] left-[-10%] w-[400px] h-[400px] rounded-full bg-blue-500/10 dark:bg-blue-500/5 blur-[100px] -z-10" />

      <div className="w-full max-w-md animate-in-fade">
        <Card className="glass-card border-zinc-200/50 dark:border-zinc-900/50 shadow-2xl relative">
          <CardHeader className="space-y-3 text-center pb-4">
            {/* Logo */}
            <div className="mx-auto flex h-12 w-12 items-center justify-center rounded-2xl bg-amber-500 text-zinc-950 font-black shadow-lg shadow-amber-500/20 select-none">
              CM
            </div>
            <div className="space-y-1">
              <CardTitle className="text-2xl font-extrabold tracking-tight text-zinc-900 dark:text-zinc-50">
                Acesse o <span className="text-amber-500">ERP + CRM</span>
              </CardTitle>
              <CardDescription className="text-zinc-500 dark:text-zinc-400 text-xs">
                Insira suas credenciais para entrar no Click Marido
              </CardDescription>
            </div>
          </CardHeader>
          <CardContent>
            {error && (
              <div className="mb-4 rounded-lg bg-red-500/10 border border-red-500/20 p-3 text-xs font-semibold text-red-600 dark:text-red-400">
                {error}
              </div>
            )}

            <form onSubmit={handleSubmit} className="space-y-4">
              {/* E-mail */}
              <div className="space-y-1.5">
                <label htmlFor="login-email" className="text-xs font-bold text-zinc-500 dark:text-zinc-400 uppercase tracking-wider">
                  E-mail institucional
                </label>
                <div className="relative">
                  <Mail className="absolute top-1/2 left-3 h-4 w-4 -translate-y-1/2 text-zinc-400" aria-hidden="true" />
                  <input
                    id="login-email"
                    type="email"
                    required
                    placeholder="nome@clickmarido.com.br"
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                    className="w-full h-11 rounded-lg border border-zinc-200 dark:border-zinc-850 bg-zinc-50/50 dark:bg-zinc-900/40 pl-10 pr-4 text-sm outline-none transition-all focus:border-amber-500 focus:ring-1 focus:ring-amber-500 text-zinc-900 dark:text-zinc-100"
                  />
                </div>
              </div>

              {/* Senha */}
              <div className="space-y-1.5">
                <div className="flex items-center justify-between">
                  <label htmlFor="login-password" className="text-xs font-bold text-zinc-500 dark:text-zinc-400 uppercase tracking-wider">
                    Senha de acesso
                  </label>
                  <Link
                    href="/esqueci-senha"
                    className="text-xs font-semibold text-amber-500 hover:text-amber-600 transition-colors"
                  >
                    Esqueceu a senha?
                  </Link>
                </div>
                <div className="relative">
                  <Lock className="absolute top-1/2 left-3 h-4 w-4 -translate-y-1/2 text-zinc-400" aria-hidden="true" />
                  <input
                    id="login-password"
                    type="password"
                    required
                    placeholder="••••••••"
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    className="w-full h-11 rounded-lg border border-zinc-200 dark:border-zinc-850 bg-zinc-50/50 dark:bg-zinc-900/40 pl-10 pr-4 text-sm outline-none transition-all focus:border-amber-500 focus:ring-1 focus:ring-amber-500 text-zinc-900 dark:text-zinc-100"
                  />
                </div>
              </div>

              {/* Botão de Submit */}
              <Button
                type="submit"
                disabled={loading}
                className="w-full h-11 bg-amber-500 hover:bg-amber-650 text-zinc-950 font-extrabold shadow-lg shadow-amber-500/10 rounded-lg flex items-center justify-center gap-2 transition-transform active:scale-95 duration-100 disabled:opacity-50"
              >
                {loading ? (
                  <>
                    <Loader2 className="h-4 w-4 animate-spin text-zinc-950" />
                    <span>Autenticando...</span>
                  </>
                ) : (
                  <>
                    <span>Entrar no Painel</span>
                    <ArrowRight className="h-4 w-4 text-zinc-950" />
                  </>
                )}
              </Button>
            </form>

            {/* Demonstração de contas */}
            <div className="mt-6 border-t border-zinc-200 dark:border-zinc-900 pt-4">
              <p className="text-[10px] font-bold text-zinc-400 uppercase text-center mb-2">
                Usuários de demonstração (Senha: senha123):
              </p>
              <div className="grid grid-cols-2 gap-1.5 text-[9px] text-zinc-500 dark:text-zinc-400">
                <div>🔑 admin@clickmarido.com.br</div>
                <div>🔧 tecnico@clickmarido.com.br</div>
                <div>📞 atendente@clickmarido.com.br</div>
                <div>💼 gestor@clickmarido.com.br</div>
              </div>
            </div>
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

'use client';

import { useState, useEffect, useMemo, useCallback } from 'react';
import useSWR from 'swr';
import { Building, Plus, Phone, Mail, MapPin, Trash2, Search, ArrowLeft, Edit, CheckCircle2, XCircle, ShieldAlert } from 'lucide-react';
import { ApiClient } from '@/lib/api/client';
import { Card, CardContent } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import Link from 'next/link';
import { useAuth } from '@/contexts/auth-context';
import { useDebounce } from '@/hooks/use-debounce';
import { DataTable } from '@/components/ui/data-table';
import { DataTablePagination } from '@/components/ui/data-table-pagination';
import { SkeletonTable } from '@/components/ui/skeleton-table';
import { FilterPanel } from '@/components/ui/filter-panel';
import { getCompanyColumns, Company } from './columns';

export default function EmpresasPage() {
  const { user } = useAuth();

  const [page, setPage] = useState(1);
  const [limit] = useState(10);

  // Estados de busca e filtros
  const [search, setSearch] = useState('');
  const [activeFilter, setActiveFilter] = useState<string>('all');
  const [stateFilter, setStateFilter] = useState('');

  // Estados de formulário/modal
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [selectedCompany, setSelectedCompany] = useState<Company | null>(null);
  const [formData, setFormData] = useState({
    name: '',
    slug: '',
    cnpj: '',
    phone: '',
    email: '',
    address: '',
    city: '',
    state: '',
    active: true,
  });
  const [formError, setFormError] = useState('');
  const [formLoading, setFormLoading] = useState(false);

  const debouncedSearch = useDebounce(search, 300);

  const swrKey = useMemo(() => {
    return ['/companies', page, limit, debouncedSearch, activeFilter, stateFilter, user];
  }, [page, limit, debouncedSearch, activeFilter, stateFilter, user]);

  const { data: swrData, isLoading, mutate: fetchCompanies } = useSWR(
    swrKey,
    ([url, p, l, s, a, st]: [string, number, number, string, string, string]) => {
      if (!user || !user.roles.includes('Administrador')) return null;
      const activeParam = a === 'active' ? 'true' : a === 'inactive' ? 'false' : '';
      return ApiClient.get<Record<string, unknown>>(url, {
        params: {
          page: String(p),
          limit: String(l),
          search: s,
          active: activeParam,
          state: st,
        },
      });
    },
    { keepPreviousData: true, dedupingInterval: 300000 }
  );

  const companies = swrData?.data?.items || [];
  const total = swrData?.data?.total || 0;
  const totalPages = swrData?.data?.totalPages || 1;
  const loading = isLoading;

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        setIsModalOpen(false);
      }
    };
    if (isModalOpen) {
      window.addEventListener('keydown', handleKeyDown);
    }
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, [isModalOpen]);

  // Se o usuário não for do perfil Administrador, bloqueia o acesso
  const isAdmin = user?.roles.includes('Administrador');
  if (!isAdmin) {
    return (
      <div className="flex flex-col items-center justify-center p-24 text-center min-h-[70vh]">
        <div className="w-20 h-20 rounded-3xl bg-red-500/10 flex items-center justify-center mb-6 text-red-500">
          <ShieldAlert className="w-10 h-10" />
        </div>
        <h3 className="text-2xl font-extrabold text-foreground tracking-tight">Acesso restrito</h3>
        <p className="text-muted-foreground mt-2 max-w-sm font-medium">
          Apenas administradores globais têm permissão para acessar o painel de gerenciamento de empresas.
        </p>
        <Link href="/dashboard" className="mt-6">
          <Button className="bg-input/40 border border-border hover:bg-input/80 text-foreground font-bold h-11 px-6 rounded-xl">
            Voltar ao Dashboard
          </Button>
        </Link>
      </div>
    );
  }

  const handleOpenCreateModal = () => {
    setSelectedCompany(null);
    setFormData({
      name: '',
      slug: '',
      cnpj: '',
      phone: '',
      email: '',
      address: '',
      city: '',
      state: '',
      active: true,
    });
    setFormError('');
    setIsModalOpen(true);
  };

  const handleOpenEditModal = (company: Company) => {
    setSelectedCompany(company);
    setFormData({
      name: company.name,
      slug: company.slug,
      cnpj: company.cnpj || '',
      phone: company.phone || '',
      email: company.email || '',
      address: company.address || '',
      city: company.city || '',
      state: company.state || '',
      active: company.active,
    });
    setFormError('');
    setIsModalOpen(true);
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value, type } = e.target;
    const val = type === 'checkbox' ? (e.target as HTMLInputElement).checked : value;

    // Auto-gera o slug no cadastro caso o nome seja alterado e o slug não tenha sido modificado manualmente
    if (name === 'name' && !selectedCompany) {
      const generatedSlug = value
        .toLowerCase()
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g, '')
        .replace(/[^a-z0-9]+/g, '-')
        .replace(/(^-|-$)+/g, '');
      setFormData((prev) => ({ ...prev, name: value, slug: generatedSlug }));
    } else {
      setFormData((prev) => ({ ...prev, [name]: val }));
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setFormError('');
    setFormLoading(true);

    const payload = Object.fromEntries(
      Object.entries(formData).map(([key, val]) => {
        if (key === 'cnpj') {
          const cleaned = val ? String(val).replace(/\D/g, '') : '';
          return [key, cleaned === '' ? null : cleaned];
        }
        return [key, val === '' ? null : val];
      })
    );

    try {
      if (selectedCompany) {
        // Editar
        const res = await ApiClient.put<{ success: boolean }>(`/companies/${selectedCompany.id}`, payload);
        if (res.success) {
          setIsModalOpen(false);
          fetchCompanies();
        }
      } else {
        // Criar
        const res = await ApiClient.post<{ success: boolean }>('/companies', payload);
        if (res.success) {
          setIsModalOpen(false);
          fetchCompanies();
        }
      }
    } catch (err: unknown) {
      setFormError(err.message || 'Erro ao salvar empresa.');
    } finally {
      setFormLoading(false);
    }
  };

  const handleDelete = async (id: string) => {
    if (!confirm('Tem certeza de que deseja excluir esta empresa? Todos os usuários vinculados serão desativados.')) return;

    try {
      const res = await ApiClient.delete<{ success: boolean }>(`/companies/${id}`);
      if (res.success) {
        fetchCompanies();
      }
    } catch (err: unknown) {
      alert(err.message || 'Erro ao excluir empresa.');
    }
  };

  const columns = useMemo(() => getCompanyColumns({
    onOpenEdit: handleOpenEditModal,
    onDelete: handleDelete,
  }), []);

  return (
    <div className="p-8 lg:p-12 max-w-6xl mx-auto space-y-10 animate-in-fade">
      {/* Header Section */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-end gap-6 border-b border-border pb-8">
        <div className="space-y-2">
          <div className="flex items-center gap-2 text-muted-foreground mb-1">
            <Link href="/dashboard" className="hover:text-primary transition-colors flex items-center gap-1 text-xs font-bold uppercase tracking-widest">
              <ArrowLeft className="w-3 h-3" /> Dashboard
            </Link>
          </div>
          <h1 className="text-4xl font-extrabold tracking-tight text-foreground flex items-center gap-4">
            <div className="p-2 rounded-2xl bg-primary/10 text-primary">
              <Building className="w-8 h-8" />
            </div>
            Empresas
          </h1>
          <p className="text-muted-foreground font-medium">
            Gerenciando <span className="text-foreground font-bold">{total}</span> empresas ativas no sistema
          </p>
        </div>
        <div className="flex w-full md:w-auto gap-3">
          <Button 
            onClick={handleOpenCreateModal}
            className="h-11 px-6 rounded-xl bg-primary hover:bg-primary/90 text-primary-foreground shadow-lg shadow-primary/20 font-bold shrink-0 ml-auto md:ml-0"
          >
            <Plus className="w-5 h-5 mr-2" />
            Nova Empresa
          </Button>
        </div>
      </div>

      {/* Filtros e Busca */}
      <FilterPanel
        search={search}
        onSearchChange={setSearch}
        searchPlaceholder="Buscar por razão social, nome fantasia, CNPJ..."
      />

      {/* Lista de Empresas */}
      <div className="space-y-4">
        {loading ? (
          <SkeletonTable columns={4} rows={10} />
        ) : (
          <DataTable
            columns={columns}
            data={companies}
            isLoading={loading}
            virtualized={companies.length > 50}
          />
        )}

        <DataTablePagination
          pageIndex={page - 1}
          pageCount={totalPages}
          pageSize={limit}
          totalItems={total}
          canPreviousPage={page > 1}
          canNextPage={page < totalPages}
          setPageIndex={(idx) => setPage(idx + 1)}
          previousPage={() => setPage(p => p - 1)}
          nextPage={() => setPage(p => p + 1)}
        />
      </div>

      {/* Modal CRUD de Empresas */}
      {isModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/70 backdrop-blur-sm p-4 animate-in-fade">
          <div className="relative w-full max-w-lg rounded-2xl glass-card border border-border/50 shadow-2xl p-6 space-y-6">
            <div>
              <h3 className="text-xl font-bold text-foreground tracking-tight">
                {selectedCompany ? 'Editar Empresa' : 'Adicionar Nova Empresa'}
              </h3>
              <p className="text-muted-foreground text-xs mt-1">
                {selectedCompany ? 'Edite as informações cadastrais da empresa.' : 'Preencha os dados abaixo para cadastrar.'}
              </p>
            </div>

            {formError && (
              <div className="p-3 rounded-lg bg-red-500/10 border border-red-500/20 text-xs font-medium text-red-500 flex items-center gap-2">
                <XCircle className="w-4 h-4 shrink-0" />
                {formError}
              </div>
            )}

            <form onSubmit={handleSubmit} className="space-y-4">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div className="space-y-1 md:col-span-2">
                  <label className="text-xs font-bold text-muted-foreground uppercase tracking-wider">Nome da Empresa</label>
                  <input
                    type="text"
                    name="name"
                    required
                    value={formData.name}
                    onChange={handleInputChange}
                    className="w-full h-10 px-3 rounded-lg bg-input/40 border border-border text-sm text-foreground focus:outline-none focus:ring-2 focus:ring-primary/20 focus:border-primary/50"
                  />
                </div>

                <div className="space-y-1">
                  <label className="text-xs font-bold text-muted-foreground uppercase tracking-wider">Slug de Acesso</label>
                  <input
                    type="text"
                    name="slug"
                    required
                    value={formData.slug}
                    onChange={handleInputChange}
                    className="w-full h-10 px-3 rounded-lg bg-input/40 border border-border text-sm text-foreground focus:outline-none focus:ring-2 focus:ring-primary/20 focus:border-primary/50 font-mono"
                    placeholder="ex-empresa"
                    disabled={!!selectedCompany}
                  />
                </div>

                <div className="space-y-1">
                  <label className="text-xs font-bold text-muted-foreground uppercase tracking-wider">CNPJ</label>
                  <input
                    type="text"
                    name="cnpj"
                    value={formData.cnpj}
                    onChange={handleInputChange}
                    className="w-full h-10 px-3 rounded-lg bg-input/40 border border-border text-sm text-foreground focus:outline-none focus:ring-2 focus:ring-primary/20 focus:border-primary/50 font-mono"
                    placeholder="Somente números"
                    maxLength={14}
                  />
                </div>

                <div className="space-y-1">
                  <label className="text-xs font-bold text-muted-foreground uppercase tracking-wider">Telefone</label>
                  <input
                    type="text"
                    name="phone"
                    value={formData.phone}
                    onChange={handleInputChange}
                    className="w-full h-10 px-3 rounded-lg bg-input/40 border border-border text-sm text-foreground focus:outline-none focus:ring-2 focus:ring-primary/20 focus:border-primary/50"
                    placeholder="(11) 99999-9999"
                  />
                </div>

                <div className="space-y-1">
                  <label className="text-xs font-bold text-muted-foreground uppercase tracking-wider">E-mail</label>
                  <input
                    type="email"
                    name="email"
                    value={formData.email}
                    onChange={handleInputChange}
                    className="w-full h-10 px-3 rounded-lg bg-input/40 border border-border text-sm text-foreground focus:outline-none focus:ring-2 focus:ring-primary/20 focus:border-primary/50"
                  />
                </div>

                <div className="space-y-1 md:col-span-2">
                  <label className="text-xs font-bold text-muted-foreground uppercase tracking-wider">Endereço Completo</label>
                  <input
                    type="text"
                    name="address"
                    value={formData.address}
                    onChange={handleInputChange}
                    className="w-full h-10 px-3 rounded-lg bg-input/40 border border-border text-sm text-foreground focus:outline-none focus:ring-2 focus:ring-primary/20 focus:border-primary/50"
                  />
                </div>

                <div className="space-y-1">
                  <label className="text-xs font-bold text-muted-foreground uppercase tracking-wider">Cidade</label>
                  <input
                    type="text"
                    name="city"
                    value={formData.city}
                    onChange={handleInputChange}
                    className="w-full h-10 px-3 rounded-lg bg-input/40 border border-border text-sm text-foreground focus:outline-none focus:ring-2 focus:ring-primary/20 focus:border-primary/50"
                  />
                </div>

                <div className="space-y-1">
                  <label className="text-xs font-bold text-muted-foreground uppercase tracking-wider">Estado (UF)</label>
                  <input
                    type="text"
                    name="state"
                    value={formData.state}
                    onChange={handleInputChange}
                    className="w-full h-10 px-3 rounded-lg bg-input/40 border border-border text-sm text-foreground focus:outline-none focus:ring-2 focus:ring-primary/20 focus:border-primary/50 uppercase"
                    maxLength={2}
                    placeholder="SP"
                  />
                </div>
              </div>

              <div className="flex items-center gap-2 pt-2">
                <input
                  type="checkbox"
                  id="active"
                  name="active"
                  checked={formData.active}
                  onChange={(e) => setFormData((prev) => ({ ...prev, active: e.target.checked }))}
                  className="rounded bg-input/40 border-border text-primary focus:ring-primary/20 cursor-pointer w-4 h-4"
                />
                <label htmlFor="active" className="text-xs font-bold text-foreground/80 uppercase tracking-wider cursor-pointer">
                  Empresa Ativa e Operacional
                </label>
              </div>

              <div className="flex justify-end gap-3 pt-4 border-t border-border">
                <Button
                  type="button"
                  onClick={() => setIsModalOpen(false)}
                  className="bg-input/40 border border-border hover:bg-input/80 text-foreground font-bold h-10 px-5 rounded-lg text-xs"
                >
                  Cancelar
                </Button>
                <Button
                  type="submit"
                  disabled={formLoading}
                  className="bg-primary hover:bg-primary/90 text-primary-foreground font-bold h-10 px-5 rounded-lg text-xs disabled:opacity-50"
                >
                  {formLoading ? 'Salvando...' : 'Salvar Empresa'}
                </Button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

'use client';

