'use client';

import { useState, useEffect } from 'react';
import { Shield, ShieldAlert, ShieldCheck, Plus, X } from 'lucide-react';
import { Warranty, getWarranties, createWarranty, updateWarrantyStatus } from '@/lib/api/modules/warranties';
import { ApiClient } from '@/lib/api/client';
import { getServiceOrders } from '@/lib/api/modules/service-orders';
import { format, differenceInDays } from 'date-fns';

export default function GarantiasPage() {
  const [warranties, setWarranties] = useState<Warranty[]>([]);
  const [loading, setLoading] = useState(true);
  const [showModal, setShowModal] = useState(false);

  // Aux data for Modal
  const [clients, setClients] = useState<Record<string, unknown>[]>([]);
  const [orders, setOrders] = useState<Record<string, unknown>[]>([]);

  const [formData, setFormData] = useState({
    clientId: '',
    serviceOrderId: '',
    type: 'ELETRICA',
    description: '',
  });

  const fetchData = async () => {
    setLoading(true);
    try {
      const data = await getWarranties();
      setWarranties(data);
    } catch(e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, []);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        setShowModal(false);
      }
    };
    if (showModal) {
      window.addEventListener('keydown', handleKeyDown);
    }
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, [showModal]);

  const handleCreate = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      await createWarranty(formData);
      setShowModal(false);
      fetchData();
    } catch (error) {
      alert('Erro ao criar garantia. Preencha todos os campos corretamente.');
    }
  };

  const handleStatusChange = async (id: string, newStatus: string) => {
    await updateWarrantyStatus(id, newStatus);
    fetchData();
  };

  const getStatusVisuals = (warranty: Warranty) => {
    if (warranty.status === 'EXPIRED') {
      return { color: 'text-rose-500 bg-rose-500/10', icon: ShieldAlert, label: 'Expirada' };
    }
    if (warranty.status === 'CLAIMED') {
      return { color: 'text-amber-500 bg-amber-500/10', icon: ShieldAlert, label: 'Acionada' };
    }
    
    const daysLeft = differenceInDays(new Date(warranty.endDate), new Date());
    if (daysLeft <= 7) {
      return { color: 'text-amber-500 bg-amber-500/10', icon: Shield, label: `Vence em ${daysLeft} dias` };
    }
    
    return { color: 'text-emerald-500 bg-emerald-500/10', icon: ShieldCheck, label: 'Ativa' };
  };

  return (
    <div className="flex-1 space-y-6 p-4 md:p-8 pt-6">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h2 className="text-3xl font-bold tracking-tight flex items-center gap-3">
            <div className="p-2 rounded-2xl bg-emerald-500/10 text-emerald-500">
              <Shield className="w-7 h-7" />
            </div>
            Garantias
          </h2>
          <p className="text-muted-foreground">Monitoramento de garantias de serviços prestados (30, 60 e 90 dias).</p>
        </div>
        <button onClick={() => setShowModal(true)} className="flex items-center gap-2 bg-emerald-500 text-white px-4 py-2 rounded-md hover:bg-emerald-600 font-medium">
          <Plus className="w-4 h-4" /> Nova Garantia
        </button>
      </div>

      <div className="glass-card border-border/50 rounded-lg overflow-x-auto shadow-sm">
        <table className="w-full text-sm text-left">
          <thead className="bg-muted/50 border-b border-border/50">
            <tr>
              <th className="px-6 py-4 font-bold text-muted-foreground uppercase text-xs">Status</th>
              <th className="px-6 py-4 font-bold text-muted-foreground uppercase text-xs">Cliente</th>
              <th className="px-6 py-4 font-bold text-muted-foreground uppercase text-xs">OS</th>
              <th className="px-6 py-4 font-bold text-muted-foreground uppercase text-xs">Tipo</th>
              <th className="px-6 py-4 font-bold text-muted-foreground uppercase text-xs">Vencimento</th>
              <th className="px-6 py-4 font-bold text-muted-foreground uppercase text-xs text-right">Ações</th>
            </tr>
          </thead>
          <tbody>
            {loading ? (
              <tr><td colSpan={6} className="px-6 py-8 text-center text-muted-foreground">Carregando garantias...</td></tr>
            ) : warranties.length === 0 ? (
              <tr><td colSpan={6} className="px-6 py-8 text-center text-muted-foreground">Nenhuma garantia registrada.</td></tr>
            ) : (
              warranties.map((w) => {
                const visuals = getStatusVisuals(w);
                const Icon = visuals.icon;
                return (
                  <tr key={w.id} className="border-b border-border/50 last:border-0 hover:bg-muted/30">
                    <td className="px-6 py-4">
                      <span className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full font-bold text-xs ${visuals.color}`}>
                        <Icon className="w-3.5 h-3.5" /> {visuals.label}
                      </span>
                    </td>
                    <td className="px-6 py-4 font-medium">{w.client?.name || '-'}</td>
                    <td className="px-6 py-4 text-muted-foreground">OS #{w.serviceOrder?.number || '-'}</td>
                    <td className="px-6 py-4">{w.type}</td>
                    <td className="px-6 py-4">{format(new Date(w.endDate), 'dd/MM/yyyy')}</td>
                    <td className="px-6 py-4 text-right">
                      <select 
                        value={w.status}
                        onChange={(e) => handleStatusChange(w.id, e.target.value)}
                        className="bg-muted border rounded px-2 py-1 text-xs outline-none"
                      >
                        <option value="ACTIVE">Ativa</option>
                        <option value="EXPIRED">Expirada</option>
                        <option value="CLAIMED">Acionada</option>
                      </select>
                    </td>
                  </tr>
                );
              })
            )}
          </tbody>
        </table>
      </div>

      {showModal && (
        <div className="fixed inset-0 bg-black/70 backdrop-blur-sm z-50 flex items-center justify-center p-4 animate-in-fade">
          <div className="glass-card border border-border/50 rounded-2xl shadow-xl w-full max-w-md p-6">
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-xl font-bold flex items-center gap-2"><Shield className="w-5 h-5 text-emerald-500" /> Registrar Garantia</h3>
              <button onClick={() => setShowModal(false)} className="text-muted-foreground hover:text-foreground"><X className="w-5 h-5" /></button>
            </div>
            <form onSubmit={handleCreate} className="space-y-4">
              
              <div>
                <label className="block text-sm font-medium mb-1">Cliente</label>
                <select required value={formData.clientId} onChange={e => setFormData({...formData, clientId: e.target.value})} className="w-full bg-background border rounded p-2 outline-none focus:border-emerald-500">
                  <option value="">Selecione...</option>
                  {clients.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                </select>
              </div>

              <div>
                <label className="block text-sm font-medium mb-1">Ordem de Serviço (OS)</label>
                <select required value={formData.serviceOrderId} onChange={e => setFormData({...formData, serviceOrderId: e.target.value})} className="w-full bg-background border rounded p-2 outline-none focus:border-emerald-500">
                  <option value="">Selecione...</option>
                  {orders.map(o => <option key={o.id} value={o.id}>OS #{o.number} - {o.client?.name}</option>)}
                </select>
              </div>

              <div>
                <label className="block text-sm font-medium mb-1">Tipo de Serviço</label>
                <select required value={formData.type} onChange={e => setFormData({...formData, type: e.target.value})} className="w-full bg-background border rounded p-2 outline-none focus:border-emerald-500">
                  <option value="ELETRICA">Elétrica (90 dias)</option>
                  <option value="HIDRAULICA">Hidráulica (90 dias)</option>
                  <option value="INSTALACAO">Instalações (60 dias)</option>
                  <option value="MARCENARIA">Marcenaria (30 dias)</option>
                </select>
              </div>

              <div>
                <label className="block text-sm font-medium mb-1">Descrição do Serviço Coberto (Opcional)</label>
                <textarea rows={3} value={formData.description} onChange={e => setFormData({...formData, description: e.target.value})} className="w-full bg-background border rounded p-2 outline-none focus:border-emerald-500" placeholder="Ex: Conserto da fiação do painel principal" />
              </div>

              <div className="pt-2">
                <button type="submit" className="w-full bg-emerald-500 text-white font-bold py-2 rounded hover:bg-emerald-600 transition-colors">
                  Gerar Garantia Automática
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { Package, Plus, Search, ArrowLeft, Trash2, Edit, TrendingUp, TrendingDown, Minus, XCircle, History, AlertTriangle } from 'lucide-react';
import { ApiClient } from '@/lib/api/client';
import { Card, CardContent } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import Link from 'next/link';

interface Material {
  id: string;
  name: string;
  category: string;
  quantity: number;
  minimumStock: number;
  averageCost: number;
  createdAt: string;
  updatedAt: string;
}

interface MaterialMovement {
  id: string;
  materialId: string;
  type: 'ENTRADA' | 'SAIDA' | 'AJUSTE';
  quantity: number;
  unitCost: number;
  description?: string;
  createdAt: string;
}

function formatCurrency(value: number): string {
  return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(value);
}

function formatNumber(value: number): string {
  return new Intl.NumberFormat('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(value);
}

export default function MateriaisPage() {
  const [materials, setMaterials] = useState<Material[]>([]);
  const [total, setTotal] = useState(0);
  const [page, setPage] = useState(1);
  const [limit] = useState(10);
  const [totalPages, setTotalPages] = useState(1);
  const [search, setSearch] = useState('');
  const [categoryFilter, setCategoryFilter] = useState('');
  const [lowStockFilter, setLowStockFilter] = useState(false);
  const [loading, setLoading] = useState(true);

  const [isFormModalOpen, setIsFormModalOpen] = useState(false);
  const [selectedMaterial, setSelectedMaterial] = useState<Material | null>(null);
  const [formData, setFormData] = useState({
    name: '',
    category: 'Hidráulico',
    quantity: '',
    minimumStock: '',
    averageCost: '',
  });
  const [formError, setFormError] = useState('');
  const [formLoading, setFormLoading] = useState(false);

  const [isMovementModalOpen, setIsMovementModalOpen] = useState(false);
  const [movementMaterial, setMovementMaterial] = useState<Material | null>(null);
  const [movementData, setMovementData] = useState({
    type: 'ENTRADA',
    quantity: '',
    unitCost: '',
    description: '',
  });
  const [movementError, setMovementError] = useState('');
  const [movementLoading, setMovementLoading] = useState(false);

  const [isHistoryModalOpen, setIsHistoryModalOpen] = useState(false);
  const [historyMaterial, setHistoryMaterial] = useState<Material | null>(null);
  const [movements, setMovements] = useState<MaterialMovement[]>([]);
  const [historyPage, setHistoryPage] = useState(1);
  const [historyTotalPages, setHistoryTotalPages] = useState(1);
  const [historyLoading, setHistoryLoading] = useState(false);

  const categories = ['Hidráulico', 'Elétrico', 'Limpeza', 'Ferramentas', 'Acabamento', 'Segurança', 'Outros'];

  const fetchMaterials = async () => {
    setLoading(true);
    try {
      const data = await ApiClient.get<{
        success: boolean;
        data: { items: Material[]; total: number; page: number; limit: number; totalPages: number };
      }>('/materials', {
        params: {
          page: String(page),
          limit: String(limit),
          search,
          category: categoryFilter,
          lowStock: lowStockFilter ? 'true' : '',
        },
      });

      if (data.success) {
        setMaterials(data.data.items);
        setTotal(data.data.total);
        setTotalPages(data.data.totalPages);
      }
    } catch (e: unknown) {
      console.error('Erro ao buscar materiais:', e.message);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchMaterials();
  }, [page, categoryFilter, lowStockFilter]);

  useEffect(() => {
    const delayDebounce = setTimeout(() => {
      setPage(1);
      fetchMaterials();
    }, 400);
    return () => clearTimeout(delayDebounce);
  }, [search]);

  const handleOpenCreateModal = () => {
    setSelectedMaterial(null);
    setFormData({ name: '', category: 'Hidráulico', quantity: '', minimumStock: '', averageCost: '' });
    setFormError('');
    setIsFormModalOpen(true);
  };

  const handleOpenEditModal = (material: Material) => {
    setSelectedMaterial(material);
    setFormData({
      name: material.name,
      category: material.category,
      quantity: String(material.quantity),
      minimumStock: String(material.minimumStock),
      averageCost: String(material.averageCost),
    });
    setFormError('');
    setIsFormModalOpen(true);
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setFormError('');
    setFormLoading(true);

    const quantity = parseFloat(formData.quantity.replace(',', '.')) || 0;
    const minimumStock = parseFloat(formData.minimumStock.replace(',', '.')) || 0;
    const averageCost = parseFloat(formData.averageCost.replace(',', '.')) || 0;

    if (!formData.name.trim()) {
      setFormError('O nome do material é obrigatório.');
      setFormLoading(false);
      return;
    }

    const payload = { name: formData.name.trim(), category: formData.category, quantity, minimumStock, averageCost };

    try {
      if (selectedMaterial) {
        const res = await ApiClient.put<{ success: boolean }>(`/materials/${selectedMaterial.id}`, payload);
        if (res.success) {
          setIsFormModalOpen(false);
          fetchMaterials();
        }
      } else {
        const res = await ApiClient.post<{ success: boolean }>('/materials', payload);
        if (res.success) {
          setIsFormModalOpen(false);
          fetchMaterials();
        }
      }
    } catch (err: unknown) {
      setFormError(err.message || 'Erro ao salvar material.');
    } finally {
      setFormLoading(false);
    }
  };

  const handleDelete = async (id: string) => {
    if (!confirm('Deseja realmente arquivar este material?')) return;
    try {
      const res = await ApiClient.delete<{ success: boolean }>(`/materials/${id}`);
      if (res.success) fetchMaterials();
    } catch (err: unknown) {
      alert(err.message || 'Erro ao arquivar material.');
    }
  };

  const handleOpenMovementModal = (material: Material) => {
    setMovementMaterial(material);
    setMovementData({ type: 'ENTRADA', quantity: '', unitCost: '', description: '' });
    setMovementError('');
    setIsMovementModalOpen(true);
  };

  const handleMovementSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!movementMaterial) return;
    setMovementError('');
    setMovementLoading(true);

    const quantity = parseFloat(movementData.quantity.replace(',', '.'));
    if (isNaN(quantity) || quantity <= 0) {
      setMovementError('A quantidade deve ser um número maior que zero.');
      setMovementLoading(false);
      return;
    }

    const unitCost = parseFloat(movementData.unitCost.replace(',', '.')) || 0;

    try {
      const res = await ApiClient.post<{ success: boolean }>(`/materials/${movementMaterial.id}/movements`, {
        materialId: movementMaterial.id,
        type: movementData.type,
        quantity,
        unitCost: movementData.type === 'ENTRADA' ? unitCost : undefined,
        description: movementData.description || undefined,
      });
      if (res.success) {
        setIsMovementModalOpen(false);
        fetchMaterials();
      }
    } catch (err: unknown) {
      setMovementError(err.message || 'Erro ao registrar movimentação.');
    } finally {
      setMovementLoading(false);
    }
  };

  const handleOpenHistory = async (material: Material) => {
    setHistoryMaterial(material);
    setHistoryPage(1);
    setIsHistoryModalOpen(true);
    setHistoryLoading(true);
    try {
      const data = await ApiClient.get<{
        success: boolean;
        data: { items: MaterialMovement[]; total: number; page: number; limit: number; totalPages: number };
      }>(`/materials/${material.id}/movements`, { params: { page: '1', limit: '10' } });
      if (data.success) {
        setMovements(data.data.items);
        setHistoryTotalPages(data.data.totalPages);
      }
    } catch (err: unknown) {
      console.error(err);
    } finally {
      setHistoryLoading(false);
    }
  };

  const loadMoreHistory = async () => {
    if (!historyMaterial || historyPage >= historyTotalPages) return;
    const nextPage = historyPage + 1;
    setHistoryLoading(true);
    try {
      const data = await ApiClient.get<{
        success: boolean;
        data: { items: MaterialMovement[]; total: number; page: number; limit: number; totalPages: number };
      }>(`/materials/${historyMaterial.id}/movements`, { params: { page: String(nextPage), limit: '10' } });
      if (data.success) {
        setMovements((prev) => [...prev, ...data.data.items]);
        setHistoryPage(nextPage);
        setHistoryTotalPages(data.data.totalPages);
      }
    } catch (err: unknown) {
      console.error(err);
    } finally {
      setHistoryLoading(false);
    }
  };

  const movementIcon = (type: string) => {
    switch (type) {
      case 'ENTRADA': return <TrendingUp className="w-3.5 h-3.5 text-emerald-400" />;
      case 'SAIDA': return <TrendingDown className="w-3.5 h-3.5 text-red-400" />;
      case 'AJUSTE': return <Minus className="w-3.5 h-3.5 text-amber-400" />;
      default: return null;
    }
  };

  const movementBadge = (type: string) => {
    switch (type) {
      case 'ENTRADA': return <Badge className="bg-emerald-500/15 text-emerald-400 border border-emerald-500/25 px-2 py-0.5 text-[10px] font-black uppercase">Entrada</Badge>;
      case 'SAIDA': return <Badge className="bg-red-500/15 text-red-400 border border-red-500/25 px-2 py-0.5 text-[10px] font-black uppercase">Saída</Badge>;
      case 'AJUSTE': return <Badge className="bg-amber-500/15 text-amber-400 border border-amber-500/25 px-2 py-0.5 text-[10px] font-black uppercase">Ajuste</Badge>;
      default: return null;
    }
  };

  return (
    <div className="p-8 lg:p-12 max-w-6xl mx-auto space-y-10 animate-in-fade">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-end gap-6 border-b border-zinc-900 pb-8">
        <div className="space-y-2">
          <div className="flex items-center gap-2 text-zinc-500 mb-1">
            <Link href="/dashboard" className="hover:text-emerald-400 transition-colors flex items-center gap-1 text-xs font-bold uppercase tracking-widest">
              <ArrowLeft className="w-3 h-3" /> Dashboard
            </Link>
          </div>
          <h1 className="text-4xl font-extrabold tracking-tight text-white flex items-center gap-4">
            <div className="p-2 rounded-2xl bg-emerald-500/10 text-emerald-500">
              <Package className="w-8 h-8" />
            </div>
            Materiais
          </h1>
          <p className="text-zinc-400 font-medium">
            Gerenciando <span className="text-white font-bold">{total}</span> materiais cadastrados
          </p>
        </div>
        <div className="flex flex-wrap w-full md:w-auto gap-3">
          <Button
            onClick={handleOpenCreateModal}
            className="h-11 px-6 rounded-xl bg-emerald-600 hover:bg-emerald-500 shadow-lg shadow-emerald-500/20 font-bold shrink-0 flex items-center gap-2"
          >
            <Plus className="w-5 h-5" />
            Novo Material
          </Button>
        </div>
      </div>

      <div className="grid gap-4 md:grid-cols-4 items-center bg-zinc-950/20 p-4 rounded-2xl border border-zinc-900/60 backdrop-blur-sm">
        <div className="relative md:col-span-2">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-zinc-500" />
          <input
            type="text"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="w-full h-11 pl-10 pr-4 rounded-xl bg-zinc-900/50 border border-zinc-800 text-sm text-white focus:outline-none focus:ring-2 focus:ring-emerald-500/20 focus:border-emerald-500/50 transition-all placeholder:text-zinc-650"
            placeholder="Buscar material pelo nome..."
          />
        </div>
        <div>
          <select
            value={categoryFilter}
            onChange={(e) => { setCategoryFilter(e.target.value); setPage(1); }}
            className="w-full h-11 px-4 rounded-xl bg-zinc-900/50 border border-zinc-800 text-sm text-white focus:outline-none focus:ring-2 focus:ring-emerald-500/20 focus:border-emerald-500/50 transition-all cursor-pointer"
          >
            <option value="">Todas as Categorias</option>
            {categories.map((cat) => (
              <option key={cat} value={cat}>{cat}</option>
            ))}
          </select>
        </div>
        <div className="flex items-center gap-2 h-11 px-4 rounded-xl bg-zinc-900/30 border border-zinc-800/50">
          <input
            type="checkbox"
            id="lowStock"
            checked={lowStockFilter}
            onChange={(e) => { setLowStockFilter(e.target.checked); setPage(1); }}
            className="w-4 h-4 rounded border-zinc-800 bg-zinc-900 text-emerald-600 focus:ring-emerald-500/25 focus:ring-offset-zinc-950 cursor-pointer"
          />
          <label htmlFor="lowStock" className="text-xs font-bold text-zinc-300 uppercase tracking-wider cursor-pointer select-none">
            Estoque Crítico
          </label>
        </div>
      </div>

      {loading ? (
        <div className="flex flex-col items-center justify-center p-24 text-center">
          <div className="animate-spin rounded-full h-10 w-10 border-b-2 border-emerald-500"></div>
          <span className="text-zinc-500 mt-4 font-semibold">Carregando materiais...</span>
        </div>
      ) : materials.length === 0 ? (
        <Card className="flex flex-col items-center justify-center p-24 text-center border-dashed border-zinc-800 glass-card">
          <div className="w-20 h-20 rounded-full bg-zinc-900 flex items-center justify-center mb-6">
            <Package className="w-10 h-10 text-zinc-700 opacity-50" />
          </div>
          <h3 className="text-xl font-bold text-zinc-300">Nenhum material encontrado</h3>
          <p className="text-zinc-500 mt-2 max-w-sm">
            Tente ajustar os filtros ou cadastre um novo material.
          </p>
        </Card>
      ) : (
        <div className="space-y-6">
          <div className="grid gap-4 sm:grid-cols-1 lg:grid-cols-2">
            {materials.map((material, idx) => {
              const isLowStock = material.quantity <= material.minimumStock;
              return (
                <Card key={material.id} className="group glass-card glow-hover border-zinc-900/50 animate-in-slide" style={{ animationDelay: `${idx * 0.05}s` }}>
                  <CardContent className="p-6">
                    <div className="flex items-start justify-between gap-4">
                      <div className="flex items-start gap-5">
                        <div className="relative shrink-0">
                          <div className={`w-14 h-14 rounded-2xl bg-gradient-to-br from-zinc-800 to-zinc-900 border flex items-center justify-center text-lg font-black transition-all ${isLowStock ? 'border-red-500/30' : 'border-zinc-700/50'}`}>
                            <Package className={`w-6 h-6 transition-colors ${isLowStock ? 'text-red-400' : 'text-zinc-500 group-hover:text-emerald-500'}`} />
