'use client';

import { useState, useEffect } from 'react';
import { History, MessageSquare, Send } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { ApiClient } from '@/lib/api/client';
import { useClientContext } from '@/contexts/client-context';

interface HistoryItem {
  id: string;
  clientId: string;
  type: 'CREATE' | 'UPDATE' | 'NOTE' | 'SYSTEM' | 'CALL' | 'VISIT' | 'WHATSAPP';
  description: string;
  createdAt: string;
  createdBy?: {
    id: string;
    name: string;
    email: string;
  };
}

export function ClientHistoryModal() {
  const { isHistoryModalOpen, setIsHistoryModalOpen, historyClient } = useClientContext();

  const [historyItems, setHistoryItems] = useState<HistoryItem[]>([]);
  const [historyLoading, setHistoryLoading] = useState(false);
  const [newNote, setNewNote] = useState('');
  const [newNoteType, setNewNoteType] = useState('NOTE');
  const [noteError, setNoteError] = useState('');
  const [noteLoading, setNoteLoading] = useState(false);

  useEffect(() => {
    if (isHistoryModalOpen && historyClient) {
      fetchHistory(historyClient.id);
    }
  }, [isHistoryModalOpen, historyClient]);

  const fetchHistory = async (clientId: string) => {
    setHistoryLoading(true);
    try {
      const res = await ApiClient.get<{ success: boolean; data: HistoryItem[] }>(`/clients/${clientId}/history`);
      if (res.success) {
        setHistoryItems(res.data);
      }
    } catch (err: unknown) {
      console.error('Erro ao carregar histórico:', err.message);
    } finally {
      setHistoryLoading(false);
    }
  };

  const handleAddNote = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newNote.trim() || !historyClient) return;

    setNoteError('');
    setNoteLoading(true);
    try {
      const res = await ApiClient.post<{ success: boolean }>(`/clients/${historyClient.id}/history`, {
        type: newNoteType,
        description: newNote.trim(),
      });

      if (res.success) {
        setNewNote('');
        await fetchHistory(historyClient.id);
      }
    } catch (err: unknown) {
      setNoteError(err.message || 'Erro ao registrar nota.');
    } finally {
      setNoteLoading(false);
    }
  };

  const getHistoryBadge = (type: string) => {
    switch (type) {
      case 'NOTE':
        return <Badge variant="outline" className="bg-blue-500/10 text-blue-400 border-blue-500/20 text-[10px]">Anotação</Badge>;
      case 'WHATSAPP':
        return <Badge variant="outline" className="bg-emerald-500/10 text-emerald-400 border-emerald-500/20 text-[10px]">WhatsApp</Badge>;
      case 'SYSTEM':
        return <Badge variant="outline" className="bg-zinc-800 text-zinc-400 border-zinc-700 text-[10px]">Sistema</Badge>;
      case 'CALL':
        return <Badge variant="outline" className="bg-indigo-500/10 text-indigo-400 border-indigo-500/20 text-[10px]">Ligação</Badge>;
      case 'VISIT':
        return <Badge variant="outline" className="bg-amber-500/10 text-amber-400 border-amber-500/20 text-[10px]">Visita</Badge>;
      default:
        return <Badge variant="outline" className="text-[10px]">{type}</Badge>;
    }
  };

  if (!isHistoryModalOpen || !historyClient) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-end bg-black/70 backdrop-blur-sm p-0 animate-in-fade">
      <div className="relative w-full max-w-lg h-full glass-card border-l border-border/50 shadow-2xl p-6 flex flex-col justify-between rounded-l-2xl">
        <div className="flex items-center justify-between border-b border-border/50 pb-4">
          <div className="flex items-center gap-3">
            <div className="p-2 rounded-xl bg-blue-500/10 text-blue-500">
              <History className="w-5 h-5" />
            </div>
            <div>
              <h3 className="text-base font-bold text-white tracking-tight">Histórico de Interações</h3>
              <p className="text-xs text-zinc-500">{historyClient.name}</p>
            </div>
          </div>
          <Button
            variant="ghost"
            size="sm"
            onClick={() => setIsHistoryModalOpen(false)}
            className="text-zinc-500 hover:text-white"
          >
            Voltar
          </Button>
        </div>

        <div className="flex-1 overflow-y-auto my-6 pr-2 space-y-6">
          {historyLoading ? (
            <div className="flex flex-col items-center justify-center p-12 text-center h-full">
              <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-500"></div>
              <span className="text-zinc-500 mt-2 text-xs">Carregando timeline...</span>
            </div>
          ) : historyItems.length === 0 ? (
            <div className="flex flex-col items-center justify-center p-12 text-center h-full">
              <MessageSquare className="w-8 h-8 text-zinc-800 mb-2" />
              <span className="text-zinc-500 text-xs">Nenhum evento registrado.</span>
            </div>
          ) : (
            <div className="relative border-l border-border/50 ml-3 pl-6 space-y-6 py-2">
              {historyItems.map((item) => (
                <div key={item.id} className="relative">
                  <span className="absolute -left-[31px] top-1.5 flex h-2 w-2 rounded-full bg-border ring-4 ring-background" />

                  <div className="space-y-1">
                    <div className="flex items-center gap-2 flex-wrap">
                      <span className="text-[10px] text-zinc-500 font-medium">
                        {new Date(item.createdAt).toLocaleString('pt-BR')}
                      </span>
                      {getHistoryBadge(item.type)}
                      {item.createdBy && (
                        <span className="text-[10px] text-zinc-400 font-bold bg-muted px-1.5 py-0.5 rounded border border-border/50">
                          Por: {item.createdBy.name}
                        </span>
                      )}
                    </div>
                    <p className="text-xs text-zinc-300 leading-relaxed font-medium">
                      {item.description}
                    </p>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>

        <div className="border-t border-border/50 pt-4">
          <form onSubmit={handleAddNote} className="space-y-3">
            {noteError && (
              <p className="text-[11px] text-red-500 font-medium">{noteError}</p>
            )}

            <div className="flex gap-2">
              <select
                value={newNoteType}
                onChange={(e) => setNewNoteType(e.target.value)}
                className="h-10 px-2 rounded-lg bg-input/40 border border-border/50 text-xs text-zinc-300 focus:outline-none cursor-pointer"
              >
                <option value="NOTE">Anotação</option>
                <option value="CALL">Ligação</option>
                <option value="VISIT">Visita</option>
                <option value="WHATSAPP">WhatsApp</option>
              </select>

              <div className="relative flex-1">
                <input
                  type="text"
                  required
                  value={newNote}
                  onChange={(e) => setNewNote(e.target.value)}
                  placeholder="Registrar nova anotação rápida..."
                  className="w-full h-10 pl-3 pr-10 rounded-lg bg-input/40 border border-border/50 text-xs text-white focus:outline-none focus:ring-1 focus:ring-blue-500/50"
                />
                <button
                  type="submit"
                  disabled={noteLoading || !newNote.trim()}
                  className="absolute right-2 top-1/2 -translate-y-1/2 text-blue-500 hover:text-blue-400 disabled:opacity-50"
                >
                  <Send className="w-4 h-4" />
                </button>
              </div>
            </div>
          </form>
        </div>
      </div>
    </div>
  );
}

'use client';

import { useMemo } from 'react';
import { useClientContext } from '@/contexts/client-context';
import { DataTable } from '@/components/ui/data-table';
import { DataTablePagination } from '@/components/ui/data-table-pagination';
import { SkeletonTable } from '@/components/ui/skeleton-table';
import { getClientColumns } from '@/app/(dashboard)/clientes/columns';
import { ApiClient } from '@/lib/api/client';

export function ClientsTable() {
  const { data, handleOpenEditModal, handleOpenHistoryModal } = useClientContext();
  const { clients, total, totalPages, page, limit, setPage, isLoading, fetchClients } = data;

  const handleDelete = async (id: string) => {
    if (!confirm('Deseja realmente arquivar este cliente do sistema?')) return;

    try {
      const res = await ApiClient.delete<{ success: boolean }>(`/clients/${id}`);
      if (res.success) {
        fetchClients();
      }
    } catch (err: unknown) {
      alert(err.message || 'Erro ao excluir cliente.');
    }
  };

  const columns = useMemo(() => getClientColumns({
    onOpenHistory: handleOpenHistoryModal,
    onOpenEdit: handleOpenEditModal,
    onDelete: handleDelete,
  }), [handleOpenHistoryModal, handleOpenEditModal]);

  return (
    <div className="space-y-4">
      {isLoading ? (
        <SkeletonTable columns={4} rows={10} />
      ) : (
        <DataTable
          columns={columns}
          data={clients}
          isLoading={isLoading}
          virtualized={clients.length > 50}
        />
      )}

      <DataTablePagination
        pageIndex={page - 1}
        pageCount={totalPages}
        pageSize={limit}
        totalItems={total}
        canPreviousPage={page > 1}
        canNextPage={page < totalPages}
        setPageIndex={(idx) => setPage(idx + 1)}
        previousPage={() => setPage(p => p - 1)}
        nextPage={() => setPage(p => p + 1)}
      />
    </div>
  );
}

"use client";

import React, { createContext, useContext, useState } from "react";
import { usePathname } from "next/navigation";
import { Sidebar } from "./sidebar";
import { Topbar } from "./topbar";

interface LayoutContextType {
  sidebarOpen: boolean;
  setSidebarOpen: (open: boolean) => void;
  sidebarCollapsed: boolean;
  setSidebarCollapsed: (collapsed: boolean) => void;
}

const LayoutContext = createContext<LayoutContextType | undefined>(undefined);

export function useLayout() {
  const context = useContext(LayoutContext);
  if (!context) {
    throw new Error("useLayout deve ser usado dentro de um LayoutProvider");
  }
  return context;
}

export function DashboardLayout({ children }: { children: React.ReactNode }) {
  const pathname = usePathname();

  // Controle para mobile (abrir/fechar gaveta)
  const [sidebarOpen, setSidebarOpen] = useState(false);
  // Controle para desktop (recolher/colapsar sidebar)
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false);

  // A renderização condicional por rota foi removida.
  // Agora o App Router usa (dashboard)/layout.tsx para este componente
  // e (auth)/layout.tsx para rotas limpas.

  return (
    <LayoutContext.Provider
      value={{
        sidebarOpen,
        setSidebarOpen,
        sidebarCollapsed,
        setSidebarCollapsed,
      }}
    >
      <div className="flex h-screen w-screen overflow-hidden bg-background text-foreground transition-colors duration-200">
        {/* Sidebar Lateral */}
        <Sidebar />

        {/* Lado Direito: Topbar + Conteúdo */}
        <div className="flex flex-1 flex-col overflow-hidden relative">
          {/* Topbar Superior */}
          <Topbar />

          {/* Área do Conteúdo Principal */}
          <main id="main-content" className="flex-1 overflow-y-auto p-4 md:p-6 bg-background text-foreground transition-colors duration-200">
            {children}
          </main>
        </div>
      </div>
    </LayoutContext.Provider>
  );
}

