import { useState, useEffect } from 'react';

export function useLocalStorage<T>(key: string, initialValue: T) {
  // State to store our value
  // Pass initial state function to useState so logic is only executed once
  const [storedValue, setStoredValue] = useState<T>(() => {
    if (typeof window === 'undefined') {
      return initialValue;
    }
    try {
      const item = window.localStorage.getItem(key);
      return item ? JSON.parse(item) : initialValue;
    } catch (error) {
      console.warn(`Error reading localStorage key "${key}":`, error);
      return initialValue;
    }
  });

  // Return a wrapped version of useState's setter function that ...
  // ... persists the new value to localStorage.
  const setValue = (value: T | ((val: T) => T)) => {
    try {
      // Allow value to be a function so we have same API as useState
      const valueToStore = value instanceof Function ? value(storedValue) : value;
      setStoredValue(valueToStore);
      if (typeof window !== 'undefined') {
        window.localStorage.setItem(key, JSON.stringify(valueToStore));
      }
    } catch (error) {
      console.warn(`Error setting localStorage key "${key}":`, error);
    }
  };

  return [storedValue, setValue] as const;
}

'use client';

import { useEffect, useRef, useCallback } from 'react';
import { io, Socket } from 'socket.io-client';

const WS_URL = process.env.NEXT_PUBLIC_WS_URL || 'http://localhost:3001';

interface UseWhatsAppSocketOptions {
  companyId?: string;
  onNewMessage?: (data: { conversation: unknown; message: unknown }) => void;
  onInstanceStatus?: (data: { instanceId: string; status: string; qrCode?: string }) => void;
  onConversationUpdate?: (data: unknown) => void;
  enabled?: boolean;
}

export function useWhatsAppSocket(options: UseWhatsAppSocketOptions) {
  const socketRef = useRef<Socket | null>(null);
  const {
    companyId,
    onNewMessage,
    onInstanceStatus,
    onConversationUpdate,
    enabled = true,
  } = options;

  useEffect(() => {
    if (!enabled || !companyId) return;

    const socket = io(`${WS_URL}/ws/whatsapp`, {
      query: { companyId },
      transports: ['websocket', 'polling'],
    });

    socketRef.current = socket;

    socket.on('connect', () => {
      socket.emit('join-company', companyId);
    });

    if (onNewMessage) {
      socket.on('new-message', onNewMessage);
    }
    if (onInstanceStatus) {
      socket.on('instance-status', onInstanceStatus);
    }
    if (onConversationUpdate) {
      socket.on('conversation-update', onConversationUpdate);
    }

    return () => {
      socket.disconnect();
      socketRef.current = null;
    };
  }, [companyId, enabled]);

  const emit = useCallback((event: string, data: unknown) => {
    socketRef.current?.emit(event, data);
  }, []);

  return { socket: socketRef.current, emit };
}

import { toast } from 'sonner';
import { useErrorStore, ApiError } from '@/store/use-error-store';

const MAX_RETRIES = 3;
const BASE_DELAY_MS = 1000;

export interface FetchOptions extends RequestInit {
  retries?: number;
}

const parseErrorResponse = async (response: Response): Promise<ApiError> => {
  try {
    const data = await response.json();
    if (data && data.error) {
      return data.error as ApiError;
    }
  } catch (e) {
    // Falha ao parsear JSON
  }

  return {
    code: `HTTP_${response.status}`,
    message: response.statusText || 'Erro inesperado no servidor',
    timestamp: new Date().toISOString(),
    path: response.url,
    requestId: 'unknown',
  };
};

export const apiFetch = async (url: string, options: FetchOptions = {}): Promise<Response> => {
  const { retries = MAX_RETRIES, ...fetchOptions } = options;
  let attempt = 0;

  while (attempt < retries) {
    try {
      const response = await fetch(url, fetchOptions);

      if (response.ok) {
        return response;
      }

      // Handle Error Responses (4xx, 5xx)
      const errorData = await parseErrorResponse(response);
      useErrorStore.getState().setLastError(errorData);

      if (response.status >= 400 && response.status < 500) {
        // Erros do cliente (ex: 400, 401, 403, 404, 409) não devem fazer retry
        toast.error(`Erro: ${errorData.message}`);
        throw new Error(errorData.message);
      }

      // Se for 5xx, prepara para retry
      if (attempt === retries - 1) {
        toast.error('O servidor não está respondendo. Tente novamente mais tarde.', {
          action: {
            label: 'Tentar Novamente',
            onClick: () => apiFetch(url, options),
          },
        });
        throw new Error(errorData.message);
      }
    } catch (error: unknown) {
      // Erro de rede (offline)
      if (!window.navigator.onLine) {
        useErrorStore.getState().addOfflineError({
          code: 'OFFLINE',
          message: 'Sem conexão com a internet',
          timestamp: new Date().toISOString(),
          path: url,
          requestId: 'unknown'
        });
        toast.error('Você está offline. Verifique sua conexão.');
        throw error;
      }

      if (attempt === retries - 1) {
        throw error;
      }
    }

    // Exponential Backoff
    attempt++;
    const delay = BASE_DELAY_MS * Math.pow(2, attempt - 1);
    await new Promise((resolve) => setTimeout(resolve, delay));
  }

  throw new Error('Falha após múltiplas tentativas');
};
